sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // 1. Parse the incoming JSON body from Postman
    var requestBody = request.body.data;

    // Fallback if data isn't automatically parsed
    if (typeof requestBody === 'string') {
        requestBody = JSON.parse(requestBody);
    }

    // Extract Application and Site data from payload
    var appData = requestBody.application_data;
    var siteData = requestBody.site_data;

    if (!appData || !siteData) {
        return new sn_ws_err.BadRequestError("Missing application_data or site_data in payload.");
    }

    try {
        // 2. Create the Site Record First
        var siteGr = new GlideRecord('x_704340_der_site');
        siteGr.initialize();

        // Map fields from payload to Site table
        if (siteData.site_id) siteGr.setValue('site_id', siteData.site_id);
        if (siteData.street_address) siteGr.setValue('street_address', siteData.street_address);
        if (siteData.city) siteGr.setValue('city', siteData.city);
        if (siteData.province) siteGr.setValue('province', siteData.province);
        if (siteData.postal_code) siteGr.setValue('postal_code', siteData.postal_code);
        if (siteData.total_site_generation) siteGr.setValue('total_site_generation_ac', siteData.total_site_generation);
        if (siteData.microgen_wires_interconnection) siteGr.setValue('microgen_wires_interconnection', siteData.microgen_wires_interconnection);

        var siteSysId = siteGr.insert();
        if (!siteSysId) {
            return new sn_ws_err.InternalError("Failed to create Site record.");
        }

        // 3. Create the DER Application Record and reference the Site immediately
        var appGr = new GlideRecord('x_704340_der_der_application');
        appGr.initialize();

        // Map fields for application
        if (appData.project_number) appGr.setValue('project_number', appData.project_number);

        // Link the newly created Site directly before doing the application insert
        appGr.setValue('site', siteSysId);

        var appSysId = appGr.insert();
        if (!appSysId) {
            return new sn_ws_err.InternalError("Failed to create Application record.");
        }

        // 4. Update the Site record with the Application reference
        // (Since your original code had a bi-directional link where both referenced each other)
        siteGr.initialize(); 
        if (siteGr.get(siteSysId)) {
            siteGr.setValue('application', appSysId);
            siteGr.update();
        }

        // 5. Send successful response back to Postman
        var responseBody = {
            "status": "Success",
            "message": "Records created and linked successfully",
            "application_sys_id": appSysId,
            "site_sys_id": siteSysId
        };
        response.setBody(responseBody);
        response.setStatus(201); // 201 Created

    } catch (ex) {
        return new sn_ws_err.InternalError("An error occurred: " + ex.message);
    }

})(request, response);
